async def seed_produto_classes(session: AsyncSession) -> int:
    """Insere classes de produto para expansão semântica."""
    inserted = 0
    for classe in PRODUTO_CLASSES:
        # Verifica se já existe
        from sqlalchemy import select
        existing = await session.execute(
            select(ProdutoClasseModel).where(ProdutoClasseModel.classe_nome == classe["classe_nome"])
        )
        if existing.scalar_one_or_none():
            continue
        
        stmt = insert(ProdutoClasseModel).values(
            classe_nome=classe["classe_nome"],
            termos_busca=classe["termos_busca"],
            marcas_referencia=classe["marcas_referencia"],
            categoria_macro=classe["categoria_macro"],
            ativo=True,
        )
        await session.execute(stmt)
        inserted += 1
    
    await session.commit()
    return inserted


async def main():
    async with AsyncSessionLocal() as session:
        count = await seed_produto_classes(session)
        print(f"✅ {count} classes de produto inseridas/atualizadas")


if __name__ == "__main__":
    import asyncio
    asyncio.run(main())